function calendar(){const [y,m]=calendarMonth.split('-').map(Number),first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),offset=(first.getDay()+6)%7;return `<label>Mois<input id="calendar-month" type="month" value="${calendarMonth}"></label><div class="calendar section-gap">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(s=>`<span class="cal-head">${s}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=`${calendarMonth}-${String(i+1).padStart(2,'0')}`,ss=core().sessions.filter(s=>s.date===d);return `<button data-calday="${d}" class="${d===today()?'today':''} ${ss.some(done)?'done':''}" aria-label="${d} : ${ss.map(s=>esc(s.title)).join(', ')||'aucune séance'}">${i+1}${ss.some(s=>!s.rest)?'<i></i>':''}</button>`}).join('')}</div>`}
function weeklyData(limit=analysisWindow,end=null){let weeks=[...new Set(core().sessions.map(s=>s.week))];const endIndex=end?weeks.findIndex(w=>String(w)===String(end)):weeks.findIndex(w=>String(w)===String(currentWeek()));if(endIndex>=0)weeks=weeks.slice(0,endIndex+1);else if(!end)weeks=weeks.filter(w=>weekRows(w)[0]?.date<=today());return weeks.slice(-limit).map(w=>{let rows=weekRows(w);if(analysisCategory!=='all')rows=rows.filter(s=>kind(s)===analysisCategory);return {week:w,rows,planned:planned(rows),a:actual(rows,'km'),load:loadStats(rows)}})}
function weeklyChart(limit=analysisWindow,end=null,type='km'){const data=weeklyData(limit,end);if(!data.length)return '<div class="empty">Pas encore de semaine à afficher.</div>';const max=Math.max(1,...data.flatMap(d=>type==='km'?[d.planned,d.a.sum]:[d.load.sum])),width=580,height=220,left=38,right=10,bottom=38,top=15,plotH=height-top-bottom,slot=(width-left-right)/data.length;return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${type==='km'?'Distance prévue et réalisée en kilomètres':'Charge réelle en unités session RPE'} par semaine"><title>${type==='km'?'Distance hebdomadaire (km)':'Charge hebdomadaire (unités session-RPE)'}</title>${[0,.25,.5,.75,1].map(f=>`<line class="gridline" x1="${left}" y1="${top+plotH*(1-f)}" x2="${width-right}" y2="${top+plotH*(1-f)}"/><text x="${left-6}" y="${top+plotH*(1-f)+3}" text-anchor="end">${fmt(max*f,0)}</text>`).join('')}${data.map((d,i)=>{const x=left+slot*i+slot*.16,bw=slot*.28;return `${type==='km'?`<rect x="${x}" y="${top+plotH*(1-d.planned/max)}" width="${bw}" height="${plotH*d.planned/max}" fill="#747580" rx="2"><title>S${d.week} prévu ${fmt(d.planned)} km</title></rect>`:''}${(type==='km'?d.a:d.load).known?`<rect x="${x+bw+3}" y="${top+plotH*(1-(type==='km'?d.a.sum:d.load.sum)/max)}" width="${bw}" height="${plotH*(type==='km'?d.a.sum:d.load.sum)/max}" fill="var(--red)" rx="2"><title>S${d.week} : ${fmt(type==='km'?d.a.sum:d.load.sum)} · ${coverage(type==='km'?d.a:d.load)}</title></rect>`:''}<text x="${left+slot*(i+.5)}" y="${height-15}" text-anchor="middle">S${esc(d.week)}${(type==='km'?d.a:d.load).known<(type==='km'?d.a:d.load).total?'*':''}</text>`}).join('')}</svg><div class="legend">${type==='km'?'<span><i class="dot planned"></i>Prévu (km)</span>':''}<span><i class="dot"></i>${type==='km'?'Réalisé (km)':'Charge calculable'}</span><span>— = absence de mesure · * = couverture partielle</span></div>`}
function trendChart(rows,key,label){const values=rows.filter(r=>num(r[key])!==null).slice(-12);if(values.length<2)return `<div class="empty">${values.length} mesure(s) de ${label.toLowerCase()} : deux valeurs minimum pour tracer une évolution.</div>`;const ys=values.map(r=>num(r[key])),min=Math.min(...ys),max=Math.max(...ys),range=max-min||1,W=560,H=185,L=45,T=18,PH=125,step=(W-L-18)/(values.length-1),y=v=>T+PH-(v-min)/range*PH;return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(label)} — ${values.length} valeurs"><title>${esc(label)} — valeurs renseignées uniquement</title>${[min,min+range/2,min+range].map(v=>`<line class="gridline" x1="${L}" y1="${y(v)}" x2="545" y2="${y(v)}"/><text x="39" y="${y(v)+3}" text-anchor="end">${key==='pace'?paceFormat(v):fmt(v)}</text>`).join('')}<polyline points="${values.map((r,i)=>`${L+i*step},${y(r[key])}`).join(' ')}" fill="none" stroke="var(--red)" stroke-width="2.5"/>${values.map((r,i)=>`<circle cx="${L+i*step}" cy="${y(r[key])}" r="3.5" fill="var(--red)"><title>${r.date} : ${key==='pace'?paceFormat(r[key]):r[key]}</title></circle>${i===0||i===values.length-1?`<text x="${L+i*step}" y="172" text-anchor="${i===0?'start':'end'}">${pretty(r.date)}</text>`:''}`).join('')}</svg>`}

function frequencyChart(){const data=weeklyData(),max=Math.max(1,...data.map(d=>d.rows.filter(done).length)),W=560,H=155,L=28,PH=105,slot=(W-L-15)/Math.max(1,data.length);if(!data.length)return '<div class="empty">Aucune semaine observée.</div>';return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Nombre de séances réalisées par semaine"><title>Fréquence hebdomadaire · séances réalisées</title><line class="gridline" x1="${L}" y1="${PH+12}" x2="545" y2="${PH+12}"/>${data.map((d,i)=>{const n=d.rows.filter(done).length,h=PH*n/max;return `<rect x="${L+slot*i+slot*.25}" y="${PH+12-h}" width="${slot*.5}" height="${h}" fill="var(--red)" rx="3"/><text x="${L+slot*(i+.5)}" y="${Math.max(12,PH+5-h)}" text-anchor="middle">${n}</text><text x="${L+slot*(i+.5)}" y="145" text-anchor="middle">S${esc(d.week)}</text>`}).join('')}</svg>`}

function analysis(){const rows=completed().filter(s=>analysisCategory==='all'||kind(s)===analysisCategory),a=actual(rows,'km'),l=loadStats(rows),data=weeklyData(),p=MagnumProgression.compare(core().sessions,today()),runs=rows.filter(s=>kind(s)==='run'&&num(s.minutes)>0&&num(s.km)>0),pace=runs.length?runs.reduce((n,s)=>n+s.minutes,0)/runs.reduce((n,s)=>n+s.km,0):null;const paceText=paceFormat;
 return heading('Analyse & progression','Les observations restent distinctes des volumes prévus.')+`<div class="controls"><label>Fenêtre des graphiques<select id="analysis-window">${[4,8,12,24,51].map(n=>`<option ${n===analysisWindow?'selected':''} value="${n}">${n} semaines</option>`).join('')}</select></label><label>Activités<select id="analysis-category">${[['all','Toutes'],['run','Course'],['trail','Marche / randonnée'],['strength','Renforcement']].map(([k,t])=>`<option value="${k}" ${analysisCategory===k?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="grid3"><section class="card">${stat(amount(a),'Km documentés · '+coverage(a),'run')}</section><section class="card">${stat(amount(l),'Charge · '+coverage(l),'health')}</section><section class="card">${stat(paceText(pace),'Allure pondérée · min/km · '+runs.length+' courses','clock')}</section></div><div class="grid2 section-gap"><section class="card"><div class="between"><h2>Volume hebdomadaire</h2><span class="badge">km</span></div>${weeklyChart()}<p class="muted">Les séances futures sont exclues des observations.</p></section><section class="card"><div class="between"><h2>Charge hebdomadaire</h2><span class="badge">min × RPE</span></div>${weeklyChart(analysisWindow,null,'load')}<p class="muted">Une absence de RPE ou durée ne vaut pas une charge nulle.</p></section><section class="card"><h2>Fréquence & progression</h2>${frequencyChart()}<div class="metric-line"><span>Séances · 7 derniers jours</span><b>${p.current.sessions}</b></div><div class="metric-line"><span>Séances · 7 jours précédents</span><b>${p.previous.sessions}</b></div><div class="metric-line"><span>Variation de charge</span><b>${p.change===null?'—':fmt(p.change,0)+' %'}</b></div><p class="muted">${p.change===null?'Comparaison suspendue : fenêtres vides, charges manquantes ou base nulle.':'Comparaison descriptive de deux fenêtres de sept jours complets.'} Cet encart porte sur toutes les activités.</p><button data-action="adapt" class="ghost section-gap">Examiner une adaptation</button></section><section class="card"><h2>Récupération · sommeil (h)</h2>${trendChart(core().health.filter(h=>h.date<=today()).sort((a,b)=>a.date.localeCompare(b.date)),'sleep','Sommeil en heures')}<button data-nav="health" class="ghost">Voir les mesures</button></section></div><section class="card section-gap"><h2>Évolution de l’allure · courses documentées</h2>${trendChart(runs.map(s=>({...s,pace:s.minutes/s.km})),'pace','Allure course (min/km)')}<p class="muted">Durée divisée par distance pour chaque course. Conditions, terrain et séances peuvent différer ; cette courbe ne prédit pas un résultat.</p></section><section class="card section-gap"><h2>Détail des semaines</h2><div class="table-wrap"><table><thead><tr><th>Semaine</th><th>Prévu km</th><th>Réalisé km</th><th>Charge</th><th>Séances</th><th>Couverture distance / charge</th></tr></thead><tbody>${data.map(d=>`<tr><td>S${esc(d.week)}</td><td>${fmt(d.planned)}</td><td>${amount(d.a)}</td><td>${amount(d.load)}</td><td>${d.rows.filter(done).length}/${d.rows.filter(s=>!s.rest&&s.date<=today()).length} échues</td><td>${coverage(d.a)} / ${coverage(d.load)}</td></tr>`).join('')}</tbody></table></div></section><section class="card section-gap"><h2>Projection de préparation</h2>${forecastPanel()}</section>`;
}
function forecastPanel(){const r=MagnumForecast.summarize(core().sessions,today());return `<p class="muted">28 derniers jours · ${r.runs} courses · ${r.known}/${r.runs} distances documentées.</p><div class="stats">${stat(fmt(r.documentedKm),'Km connus','run')}${stat(fmt(r.longest),'Sortie maximale connue (km)','trail')}${stat(fmt(r.weeklyAverage),'Moyenne observée (km/sem.)','analysis')}</div><div class="notice">${r.runs<8||r.unknown?'Historique trop court ou incomplet pour une estimation chronométrique fiable.':'L’historique permet de décrire la préparation ; il ne permet pas de prédire un résultat fiable à lui seul.'} Objectif Düsseldorf : terminer.</div><details><summary>Scénario de volume · hypothèse, pas prévision</summary><label>Facteur appliqué au volume prévu des 14 prochains jours<select id="scenario-factor"><option value="1">Programme officiel · 100 %</option><option value="0.75">Allégement hypothétique · 75 %</option><option value="0.5">Allégement hypothétique · 50 %</option></select></label><p id="scenario-value" class="muted section-gap">${fmt(planned(core().sessions.filter(s=>s.date>=today()&&s.date<=shift(today(),13))))} km prévus sur 14 jours. Aucune séance modifiée.</p></details>`}
function health(){const h=latestHealth(),rows=core().health.filter(h=>healthFilter==='all'||healthFilled(h)).sort((a,b)=>b.date.localeCompare(a.date));return heading('Santé & récupération','Mesures personnelles, tendances descriptives et ressenti.',`<button data-action="new-health" class="primary">+ Mesures</button>`)+`<div class="grid2"><section class="card"><div class="between"><h2>Dernière observation</h2><span class="badge">${h?pretty(h.date):'À renseigner'}</span></div><div class="health-cards"><div class="health-tile">${icon('health')}<div><small>RHR · FC repos</small><b>${fmt(h?.restHr,0)} <span class="unit">bpm</span></b></div></div><div class="health-tile hrv">${icon('spark')}<div><small>HRV</small><b>${fmt(h?.hrv,0)} <span class="unit">ms</span></b></div></div><div class="health-tile sleep wide">${icon('rest')}<div><small>Sommeil</small><b>${sleepText(h?.sleep)}</b></div></div><div class="health-tile">${icon('weight')}<div><small>Poids</small><b>${fmt(h?.weight,2)} <span class="unit">kg</span></b></div></div><div class="health-tile">${icon('health')}<div><small>Fatigue ressentie</small><b>${fmt(h?.fatigue)} <span class="unit">/10</span></b></div></div></div><p class="muted section-gap">${h?'Valeurs de la date indiquée ; les champs vides sont inconnus.':'Aucune donnée personnelle chargée. Les valeurs de la maquette ne sont pas utilisées.'}</p>${h?`<button data-health="${h.date}" class="ghost section-gap">Modifier cette observation</button>`:''}</section><section class="card"><h2>Récupération & vigilance</h2>${recoveryFlags().map(f=>`<div class="notice">${esc(f)}</div>`).join('')}<p class="muted">${core().health.filter(h=>h.date>=shift(today(),-13)&&h.date<=today()&&healthFilled(h)).length} journée(s) renseignée(s) sur 14 jours. Trois observations minimum pour commencer une comparaison descriptive.</p><p class="safety">Aucune conclusion médicale automatique. Une douleur inhabituelle ou persistante mérite un avis professionnel. Aucune modification du programme sans validation.</p><button data-action="adapt" class="ghost section-gap">Examiner le plan</button></section></div><div class="grid2 section-gap"><section class="card"><h2>Sommeil · heures</h2>${trendChart(core().health.filter(h=>h.date<=today()).sort((a,b)=>a.date.localeCompare(b.date)),'sleep','Sommeil (h)')}</section><section class="card"><h2>HRV · millisecondes</h2>${trendChart(core().health.filter(h=>h.date<=today()).sort((a,b)=>a.date.localeCompare(b.date)),'hrv','HRV (ms)')}<p class="muted">Le HRV ne figure pas dans Excel 3.6 ; il est conservé en JSON.</p></section></div><section class="card section-gap"><div class="between"><h2>Historique des mesures</h2><label>Afficher<select id="health-filter"><option value="filled">Dates renseignées</option><option value="all" ${healthFilter==='all'?'selected':''}>Toutes les dates importées</option></select></label></div>${rows.slice(0,120).map(h=>`<div class="row"><div class="info"><strong>${pretty(h.date)} ${h.date>today()?'<span class="badge">Date future</span>':''}</strong><small>${fmt(h.weight,2)} kg · sommeil ${sleepText(h.sleep)} · RHR ${fmt(h.restHr,0)} · HRV ${fmt(h.hrv,0)}</small><small>Fatigue ${fmt(h.fatigue)}/10 · douleur ${fmt(h.pain)}/10 · stress ${fmt(h.stress)}/10</small>${h.notes?`<small>${esc(h.notes)}</small>`:''}</div><button data-health="${h.date}">Modifier</button></div>`).join('')||'<div class="empty">Aucune observation. Ajoute tes premières mesures.</div>'}</section>`}
const trailChecks=[['equipment','Vérifier tente, couchage, eau et navigation'],['route','Préparer les étapes WHW / Skye et les alternatives'],['gps','Contrôler les traces sur GPSMAP 67i'],['safety','Contacts, points de sortie et protocole solo'],['load','Tester le sac réellement chargé'],['dress','Répétition générale de trois jours']];
const gear=[['Navigation','GPSMAP 67i, cartes papier et itinéraires hors ligne'],['Sécurité','Communication satellite, contacts et points de repli'],['Couchage','Tente, tapis, sac et protection pluie'],['Eau','Filtre et capacité adaptée'],['Énergie','Batteries, câbles, adaptateur UK'],['Vêtements','Couche chaude et protection pluie complète'],['Santé','Trousse, ampoules, hygiène'],['Logistique','Ravitaillement, gaz, transports, étapes'],['Terrain','Trois jours consécutifs avec le matériel prévu'],['Préparation','Six jours WHW et six jours Skye, marge météo']];
function trail(){const packs=state.pack.slice().sort((a,b)=>b.date.localeCompare(a.date)),strength=state.ultimate.strength.slice().sort((a,b)=>b.date.localeCompare(a.date));const prep=core().sessions.filter(s=>s.date>=today()&&['trail','strength'].includes(kind(s))).slice(0,6);return heading('Randonnée / Trail','Deux itinéraires. Une préparation progressive.')+`<div class="hero trail"><div><span class="badge">ÉCOSSE · ÉTÉ 2027 · SOLO</span><h2>West Highland Way<br>& Skye Trail.</h2><small>Six jours par trail · dates exactes à confirmer</small></div></div><div class="grid2 section-gap"><section class="card"><div class="between"><h2>Préparation expédition</h2><span class="badge red">${trailChecks.filter(([k])=>state.trail[k]).length}/${trailChecks.length}</span></div>${trailChecks.map(([k,t])=>`<label class="check"><input type="checkbox" data-check="${k}" ${state.trail[k]?'checked':''}><span>${t}</span></label>`).join('')}<p class="safety">Liste personnelle : cocher ne constitue pas une validation de sécurité. Les cartes et le guidage terrain ne sont pas fournis par ce Companion.</p><button data-action="trail-export" class="ghost section-gap">Exporter la préparation</button></section><section class="card"><h2>Prochaines séances de préparation</h2><p class="muted">Volumes, renforcement et sac prévu issus d’Excel 3.6.</p><div class="section-gap">${prep.map(sessionCard).join('')||'<div class="empty">Aucune séance de préparation à venir.</div>'}</div></section><section class="card"><div class="between"><h2>Marches avec sac</h2><button data-action="new-pack" class="primary">+ Marche</button></div><div class="stats">${stat(packs.filter(p=>p.date<=today()).length,'Marches documentées','trail')}${stat(fmt(packs.filter(p=>p.date<=today()).reduce((n,p)=>n+p.km,0)),'Km de portage','run')}${stat(packs.find(p=>p.date<=today())?fmt(packs.find(p=>p.date<=today()).weight):'—','Dernier sac (kg)','weight')}</div><p class="muted section-gap">Journal complémentaire distinct des séances ALBA : pas de double comptage dans l’analyse.</p>${packs.map(p=>`<div class="row"><div class="info"><strong>${pretty(p.date)} · ${fmt(p.km)} km</strong><small>Sac ${fmt(p.weight)} kg · D+ ${fmt(p.ascent,0)} m · RPE ${fmt(p.rpe)}</small></div><button data-pack="${esc(p.id)}">Modifier</button></div>`).join('')||'<div class="empty">Aucune marche enregistrée.</div>'}</section><section class="card"><div class="between"><h2>Renforcement progressif</h2><button data-action="new-strength">+ Séance</button></div><p class="muted">Repères indicatifs, à adapter selon le ressenti. Aucun volume ajouté automatiquement au plan.</p><div class="row"><div><strong>1 · Appropriation</strong><small>2 séries contrôlées : squat, step-up, pont fessier, mollets, gainage.</small></div></div><div class="row"><div><strong>2 · Consolidation</strong><small>Après tolérance satisfaisante : 3 séries, puis une variable à la fois. Noter le RPE.</small></div></div><div class="row"><div><strong>3 · Spécificité randonnée</strong><small>Step-up, contrôle en descente, stabilité et marche chargée selon les séances Excel.</small></div></div>${strength.map(s=>`<div class="row"><div class="info"><strong>${pretty(s.date)} · ${esc(s.type)}</strong><small>${fmt(s.minutes)} min · RPE ${fmt(s.rpe)} · ${esc(s.notes||'')}</small></div><button data-strength="${esc(s.id)}">Modifier</button></div>`).join('')||'<p class="muted">Aucun renforcement complémentaire enregistré.</p>'}</section><section class="card"><h2>Répétition générale · 3 jours</h2><p class="muted">Trois jours consécutifs à choisir avant le départ. Consigne chaque journée dans le journal de portage.</p>${['Jour 1 · Montage, eau, repas et navigation','Jour 2 · Portage en fatigue et autonomie','Jour 3 · Rangement humide, récupération et bilan'].map((s,i)=>`<label class="check"><input type="checkbox" data-check="rehearsal-${i}" ${state.trail['rehearsal-'+i]?'checked':''}><span>${s}</span></label>`).join('')}<p class="safety">N’augmente pas simultanément poids, distance et dénivelé. Les valeurs du plan restent la référence ; adapte selon les contraintes terrain et le ressenti.</p></section><section class="card"><h2>Équipement & autonomie</h2><p class="muted">Contrôles de préparation ; ne constitue pas un inventaire de possession.</p>${gear.map(([k,t])=>`<label class="check"><input type="checkbox" data-gear="${k}" ${state.ultimate.equipment[k]?'checked':''}><span><strong>${k}</strong><small>${t}</small></span></label>`).join('')}</section><section class="card full"><h2>Notes d’expédition</h2><form id="notes-form" class="section-gap"><label>Ravitaillement, itinéraires, contacts et stratégie<textarea name="notes" rows="5">${esc(state.extras.notes||'')}</textarea></label><button class="primary section-gap">Enregistrer les notes</button></form></section></div>`}
const eventDefs=[{id:'duesseldorf',name:'Marathon de Düsseldorf',when:'18 avril 2027',date:'2027-04-18',goal:'Terminer',k:'run'},{id:'trails',name:'West Highland Way + Skye Trail',when:'Été 2027 · dates exactes à fixer',date:null,goal:'Solo · six jours chacun',k:'trail'},{id:'cologne',name:'Marathon de Cologne',when:'3 octobre 2027 · date inscrite dans Excel 3.6',date:'2027-10-03',goal:'Date de plan à confirmer auprès de l’organisateur',k:'run'}];
function events(){const selected=state.settings.event;return heading('Les trois horizons','Un mode dédié pour chaque objectif, sans supprimer le plan.')+`<div class="hero"><div><span class="badge">PROJET ALBA · 2026 / 2027</span><h2>Du premier départ<br>au dernier sommet.</h2></div></div><div class="grid3 section-gap">${eventDefs.map(e=>`<section class="card"><span class="badge">${icon(e.k)} ${e.id==='trails'?'EXPÉDITION':'MARATHON'}</span><h2 class="section-gap">${e.name}</h2><p class="muted section-gap">${e.when}</p><p>${e.goal}</p>${e.date?`<div class="metric-line"><span>Compte à rebours</span><b>${MagnumEvents.daysUntil(e.date,today())} jours</b></div>`:''}<button data-event="${e.id}" class="${selected===e.id?'primary':'ghost'} section-gap">${selected===e.id?'Mode actif':'Activer le mode événement'}</button></section>`).join('')}</div>${selected!=='none'?eventPanel(selected):''}<section class="card section-gap"><h2>Préparation observée</h2>${forecastPanel()}</section>`}
function eventPanel(id){const e=eventDefs.find(e=>e.id===id);if(!e)return '';const names=id==='trails'?['Vérifier météo, replis et horaires de contact','Charger GPX/cartes sur GPSMAP 67i et cartes papier','Contrôler eau, repas, gaz, abri et énergie']:['Préparer tenue testée, dossard et transport','Vérifier départ, ravitaillement et logistique auprès de l’organisateur','Noter une stratégie prudente et le ressenti du jour'];return `<section class="card section-gap"><div class="between"><h2>${icon(e.k)} Mode ${e.name}</h2><button data-event="none">Quitter ce mode</button></div><p class="muted">Vue de préparation dédiée. Le calendrier principal reste intact.</p>${names.map((s,i)=>`<label class="check"><input data-check="event-${id}-${i}" type="checkbox" ${state.trail['event-'+id+'-'+i]?'checked':''}><span>${s}</span></label>`).join('')}<label class="section-gap">Notes de cet objectif<textarea id="event-notes">${esc(state.extras['event-'+id]||'')}</textarea></label><button data-save-event="${id}" class="primary section-gap">Enregistrer la stratégie</button><button data-nav="plan" class="ghost section-gap">Revenir au plan</button></section>`}
function dataView(){return heading('Données & sauvegardes','Companion indépendant · échanges à la demande.')+`<div class="notice">Stockage sur cet appareil et cette adresse web. Pour changer d’adresse ou d’application installée, exporte une sauvegarde complète puis restaure-la ici. Aucune synchronisation avec Excel ou Garmin n’est automatique.</div><div class="grid2"><section class="card"><h2>Importer Excel ALBA 3.6</h2><p class="muted">Le fichier original reste intact. Aperçu, contrôle des lignes et confirmation avant fusion. Les saisies locales absentes du fichier sont conservées.</p><label class="section-gap">Classeur .xlsx<input id="excel-input" type="file" accept=".xlsx"></label><div id="import-preview">${pendingImport?importPreview():''}</div><p class="safety">${core().importedAt?'Dernier import : '+esc(new Date(core().importedAt).toLocaleString('fr-FR')):'Aucun historique importé.'}</p></section><section class="card"><h2>Exports & sauvegarde complète</h2><p class="muted">Le JSON contient tous les modules, préférences et le modèle Excel importé. Le CSV exporte le journal détaillé.</p><div class="actions"><button data-action="backup" class="primary">${icon('download')} Sauvegarde complète JSON</button><button data-action="csv-export">Exporter journal CSV</button><button data-action="health-csv">Exporter santé CSV</button><button data-action="excel-export" ${!state.template?'disabled':''}>Exporter une copie Excel 3.6</button></div><p class="safety">Export Excel disponible après import du classeur. Seules les colonnes compatibles du Journal et de Poids & santé sont réécrites. Formules et autres feuilles conservées ; recalcul à l’ouverture dans Excel. Adaptations, HRV et séances libres restent dans JSON/CSV.</p></section><section class="card"><h2>Restaurer un JSON</h2><p class="muted">Compatible avec la sauvegarde complète de l’ancien Companion et le JSON journal simple. Validation intégrale avant remplacement. Une copie locale préalable est conservée.</p><label class="section-gap">Sauvegarde .json<input id="restore-input" type="file" accept=".json,application/json"></label><div id="restore-preview">${pendingRestore?restorePreview():''}</div><div class="actions"><button data-action="previous-export">Exporter l’état avant restauration</button><button data-action="raw-export">Exporter les données brutes locales</button></div></section><section class="card"><h2>Garmin · import manuel CSV</h2><p class="muted">CSV de Garmin Connect en km. Vérifie dates et unités dans l’aperçu, puis confirme chaque correspondance. Aucun fichier FIT, TCX ou GPX n’est importé ici.</p><label class="section-gap">Activités CSV<input id="garmin-input" type="file" accept=".csv,text/csv"></label><div id="garmin-preview">${garminPreview()}</div><p class="safety">Les CSV en miles doivent être convertis en kilomètres avant import. Un rapprochement ambigu impose un choix manuel. Une séance déjà renseignée ne peut pas être écrasée.</p></section><section class="card"><h2>État du Companion</h2><div class="metric-line"><span>Version du schéma</span><b>2</b></div><div class="metric-line"><span>Plan / journal</span><b>${core().sessions.length} lignes</b></div><div class="metric-line"><span>Santé renseignée</span><b>${core().health.filter(healthFilled).length} dates</b></div><div class="metric-line"><span>Modèle Excel conservé</span><b>${state.template?'Oui':'Non'}</b></div><div class="metric-line"><span>Application hors ligne</span><b id="offline-ready">Vérification…</b></div><p class="muted">Le navigateur peut effacer ses données. Garde régulièrement un JSON en dehors de l’application.</p><button data-action="persist" class="ghost section-gap">Demander un stockage persistant</button></section></div>`}
function importPreview(){return `<div class="notice"><strong>Aperçu contrôlé</strong><p>${pendingImport.parsed.sessions.length} journées · ${pendingImport.parsed.matched} lignes Journal rapprochées · ${pendingImport.parsed.health.length} dates santé.</p><p>${pendingImport.conflicts.length} conflit(s) : ${pendingImport.conflicts.slice(0,5).map(c=>esc(c)).join(' ; ')||'aucun'}.</p><p>Les valeurs locales renseignées seront conservées en cas de conflit. Le plan officiel vient du classeur. Confirmer consigne cette règle.</p><button data-action="commit-import" class="primary">Confirmer l’import et conserver les conflits locaux</button></div>`}
function restorePreview(){return `<div class="notice"><strong>Sauvegarde valide</strong><p>${pendingRestore.core.sessions.length} séances · ${pendingRestore.core.health.length} dates santé · ${pendingRestore.pack.length} portages.</p><p>La restauration remplacera tous les modules et préférences. Une copie de l’état actuel sera créée avant remplacement.</p><button data-action="commit-restore" class="primary">Restaurer toutes les données</button></div>`}
function garminPreview(){return garminRows.map((r,i)=>`<div class="row"><div class="info"><strong>Ligne ${r.line} · ${esc(r.date||'date invalide')}</strong><small>${esc(r.title)} · ${fmt(r.km)} km · ${fmt(r.minutes)} min</small><label>Correspondance<select id="garmin-match-${i}"><option value="">Choisir une séance</option>${r.matches.map(m=>`<option value="${esc(m.id)}" ${r.matches.length===1?'selected':''}>${esc(m.title)}</option>`).join('')}</select></label><small>${esc(r.status)}</small><button data-garmin="${i}" ${!r.date||!r.matches.length||r.applied?'disabled':''}>${r.applied?'Importée':'Confirmer cette activité'}</button></div></div>`).join('')}
function settings(){return heading('Paramètres','Ton environnement ALBA.')+`<div class="grid2"><section class="card"><h2>Apparence</h2><label class="section-gap">Thème<select id="theme-select">${[['auto','Automatique · système'],['dark','Graphite & rouge profond'],['light','Ivoire & bordeaux']].map(([k,t])=>`<option value="${k}" ${state.settings.theme===k?'selected':''}>${t}</option>`).join('')}</select></label><button data-action="customize-from-settings" class="ghost section-gap">Personnaliser le tableau de bord</button></section><section class="card"><h2>Installation Samsung</h2><p class="install-help section-gap">Ouvre l’adresse de test en HTTPS dans Chrome. Utilise « Installer l’application » ou le menu ⋮ → Ajouter à l’écran d’accueil. Ouvre une fois toutes les rubriques en ligne avant de vérifier le mode avion.</p><button data-action="install" class="primary section-gap">Installer l’application</button><p class="muted section-gap">Si le navigateur ne propose pas l’installation, utilise son menu. Une adresse de test différente crée une application et un stockage séparés.</p></section><section class="card"><h2>Mises à jour</h2><p class="muted section-gap">La nouvelle version attend ta confirmation avant activation. Les données locales ne sont pas supprimées lors du changement de cache.</p><button data-action="check-update" class="ghost section-gap">Rechercher une mise à jour</button></section><section class="card"><h2>À propos & limites</h2><p class="muted section-gap">MAGNUM OPUS ALBA 4.0 · schéma 2. Le plan embarqué reproduit les 357 journées d’Excel 3.6 fourni. Photographies décoratives extraites de la maquette officielle. Polices Manrope / Inter intégrées pour le fonctionnement hors ligne.</p><p class="safety">Aucun historique de démonstration, aucune connexion Garmin automatique, aucune navigation GPS ni validation médicale. Le Companion n’est pas un outil de secours.</p></section></div>`}
function render(){shell();document.title=`MAGNUM OPUS · ${labels[view]}`;if(blocked){$('main').innerHTML=heading('Données protégées','Le stockage existant n’a pas pu être lu.')+`<section class="card"><div class="notice">${esc(blocked)}</div><p>Les anciennes données n’ont pas été écrasées. Exporte les données brutes pour récupération.</p><button data-action="raw-export" class="primary section-gap">Exporter les données brutes</button><label class="section-gap">Restaurer une sauvegarde valide<input id="restore-input" type="file" accept=".json"></label><div id="restore-preview"></div></section>`;return}$('main').innerHTML=(state.settings.event!=='none'&&view!=='events'?`<div class="event-mode between"><span>Mode événement · ${esc(eventDefs.find(e=>e.id===state.settings.event)?.name||'')}</span><button data-nav="events">Ouvrir</button></div>`:'')+(core().testFixture?'<div class="notice">JEU DE TEST ANONYME · valeurs fictives de validation</div>':'')+({home,plan,analysis,health,trail,events,data:dataView,settings})[view]();if(view==='data')checkOffline()}
function showSheet(title,body){$('sheetBody').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Fermer">${icon('close')}</button></div>${body}`;if(!$('sheet').open)$('sheet').showModal()}
function closeSheet(){if($('sheet').open)$('sheet').close()}
const field=(label,name,type='number',v='',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(v??'')}" ${attrs}></label>`;
function sessionSheet(id){const s=core().sessions.find(s=>s.id===id);if(!s)return;const ad=state.adaptations[id];showSheet('Séance',`<div class="hero"><div><span class="badge">${pretty(s.date)} · S${esc(s.week)}</span><h2>${esc(s.title)}</h2><small>${esc(s.phase||s.category)}</small></div></div><div class="stats">${stat(fmt(s.plannedKm),'Km prévus','run')}${stat(fmt(s.plannedMinutes,0),'Minutes prévues','clock')}${stat(fmt(s.plannedRpe),'RPE prévu','health')}</div>${has(s.plannedPackKg)?`<p class="muted section-gap">Sac prévu : ${fmt(s.plannedPackKg)} kg</p>`:''}${ad?`<div class="notice">Adaptation validée : ${ad.factor===0?'repos proposé':fmt((s.plannedKm||0)*ad.factor)+' km / '+fmt((s.plannedMinutes||0)*ad.factor,0)+' min proposés'}. ${esc(ad.reason)}<button data-cancel-adaptation="${esc(id)}">Annuler l’adaptation</button></div>`:''}<p class="safety">Objectif : ${esc(s.category)} · effort de référence RPE ${fmt(s.plannedRpe)}. Pour les séances longues, préparer hydratation et ravitaillement testés selon les conditions. Le programme officiel reste affiché ci-dessus.</p><form id="session-form" data-id="${esc(s.id)}" class="fields section-gap"><label class="wide">Statut<select name="status">${[...new Set(['','Prévu','Réalisé','Adapté','Manqué','Repos','Blessure','Annulé','Non réalisé','Reporté',s.status||''])].map(v=>`<option ${s.status===v?'selected':''} value="${v}">${v||'Non renseigné'}</option>`).join('')}</select></label>${field('Durée réelle (min)','minutes','number',s.minutes,'min="0" max="10000" step="0.1"')}${field('Distance réelle (km)','km','number',s.km,'min="0" max="1000" step="0.01"')}${field('RPE réel /10','rpe','number',s.rpe,'min="0" max="10" step="1"')}${field('Douleur /10','pain','number',s.pain,'min="0" max="10"')}${field('Sac réel (kg)','packKg','number',s.packKg,'min="0" max="60" step="0.1"')}${field('FC moyenne séance (bpm)','avgHr','number',s.avgHr,'min="0" max="250"')}${field('Sommeil (h)','sleep','number',s.sleep,'min="0" max="24" step="0.1"')}${field('Fatigue avant /10','fatigue','number',s.fatigue,'min="0" max="10"')}${field('Chaussure','shoe','text',s.shoe)}${field('Météo','weather','text',s.weather)}<label class="wide">Notes<textarea name="notes">${esc(s.notes||'')}</textarea></label>${has(s.restHr)?`<p class="wide muted">FC historique ambiguë : ${esc(s.restHr)}. L’ancienne application ne distinguait pas FC moyenne et repos ; cette valeur n’est pas réinterprétée.</p>`:''}<button class="primary wide">Enregistrer la séance</button></form>`)}
function healthSheet(d=today()){const h=core().health.find(h=>h.date===d)||{date:d};showSheet('Mesures de santé',`<p class="muted">Vider un champ efface sa valeur. Un champ vide reste inconnu.</p><form id="health-form" data-date="${d}" class="fields section-gap">${field('Date','date','date',d,core().health.some(x=>x.date===d)?'required readonly':'required')}${field('Poids (kg)','weight','number',h.weight,'min="0" max="500" step="0.01"')}${field('Sommeil (heures décimales)','sleep','number',h.sleep,'min="0" max="24" step="0.1"')}${field('FC repos / RHR (bpm)','restHr','number',h.restHr,'min="0" max="250"')}${field('HRV (ms)','hrv','number',h.hrv,'min="0" max="1000" step="0.1"')}${field('Fatigue /10','fatigue','number',h.fatigue,'min="0" max="10"')}${field('Douleur /10','pain','number',h.pain,'min="0" max="10"')}${field('Stress /10','stress','number',h.stress,'min="0" max="10"')}<label class="wide">Notes<textarea name="notes">${esc(h.notes||'')}</textarea></label><small class="wide">Exemple : 7 h 30 = 7,5 heures. HRV conservé en JSON, hors schéma Excel 3.6.</small><button class="primary wide">Enregistrer les mesures</button>${core().health.some(x=>x.date===d)?`<button type="button" class="danger wide" data-delete-health="${d}">Effacer les mesures de cette date</button>`:''}</form>`)}
function packSheet(id){const p=state.pack.find(p=>p.id===id)||{date:today()};showSheet('Journal de portage',`<form id="pack-form" data-id="${esc(id||'')}" class="fields">${field('Date','date','date',p.date,'required')}${field('Distance (km)','km','number',p.km,'required min="0" max="100" step="0.1"')}${field('Sac réel (kg)','weight','number',p.weight,'required min="0" max="60" step="0.1"')}${field('Dénivelé positif (m)','ascent','number',p.ascent,'min="0" max="10000"')}${field('RPE /10','rpe','number',p.rpe,'min="0" max="10"')}<button class="primary wide">Enregistrer la marche</button>${id?`<button type="button" class="danger wide" data-delete-pack="${esc(id)}">Supprimer cette marche</button>`:''}</form>`)}
function strengthSheet(id){const s=state.ultimate.strength.find(s=>s.id===id)||{date:today(),type:'Renforcement A'};showSheet('Renforcement',`<form id="strength-form" data-id="${esc(id||'')}" class="fields">${field('Date','date','date',s.date,'required')}<label>Séance<select name="type">${['Renforcement A','Renforcement B','Mobilité','Marche technique'].map(t=>`<option ${s.type===t?'selected':''}>${t}</option>`).join('')}</select></label>${field('Durée (min)','minutes','number',s.minutes,'required min="1" max="240" step="0.1"')}${field('RPE /10','rpe','number',s.rpe,'required min="0" max="10"')}<label class="wide">Notes<textarea name="notes">${esc(s.notes||'')}</textarea></label><button class="primary wide">Enregistrer</button>${id?`<button type="button" class="danger wide" data-delete-strength="${esc(id)}">Supprimer</button>`:''}</form>`)}
function newSession(){showSheet('Journal libre',`<p class="muted">Activité supplémentaire, sans modification du programme officiel. Exportée en JSON/CSV.</p><form id="new-session-form" class="fields section-gap">${field('Date','date','date',today(),'required')}${field('Intitulé','title','text','','required maxlength="150"')}<label>Catégorie<select name="category"><option>Course EF</option><option>Randonnée</option><option>Renforcement</option><option>Marche</option><option>Autre</option></select></label>${field('Durée réelle (min)','minutes','number','','min="0" max="10000" step="0.1"')}${field('Distance réelle (km)','km','number','','min="0" max="1000" step="0.01"')}${field('RPE réel /10','rpe','number','','min="0" max="10"')}<button class="primary wide">Ajouter au journal</button></form>`)}
function adaptSheet(){const next=core().sessions.filter(s=>!s.rest&&s.date>=today()&&s.status!=='Réalisé').sort((a,b)=>a.date.localeCompare(b.date));showSheet('Adaptation à valider',`<p class="muted">Une adaptation est enregistrée séparément du plan Excel. Le programme original reste intact. Tu choisis la séance et confirmes l’action.</p>${alerts().map(m=>`<div class="notice">${esc(m)}</div>`).join('')}<form id="adapt-form" class="fields"><label class="wide">Séance<select name="id" required>${next.slice(0,30).map(s=>`<option value="${esc(s.id)}">${s.date} · ${esc(s.title)}</option>`).join('')}</select></label><label class="wide">Proposition<select name="factor"><option value="0.75">Alléger distance et durée de 25 %</option><option value="0">Remplacer par récupération / repos</option></select></label><label class="wide">Motif<textarea name="reason" required maxlength="2000" placeholder="Ressenti, fatigue, organisation…"></textarea></label><button class="primary wide" ${next.length?'':'disabled'}>Valider explicitement l’adaptation</button></form><details><summary>Historique des décisions (${state.ultimate.decisions.length})</summary>${state.ultimate.decisions.slice(-10).reverse().map(d=>`<div class="row"><div><strong>${esc(d.date)} · ${esc(d.action)}</strong><small>${esc(d.suggestion||d.reason||'')}</small></div></div>`).join('')}</details>`)}
function download(name,content,mime='application/json'){const blob=content instanceof Blob?content:new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportCSV(rows,fields,name){const cell=v=>{let s=text(v);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};download(name,'\ufeff'+[fields,...rows.map(r=>fields.map(f=>r[f]??''))].map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function mergeExcel(parsed){const filled=has,conflicts=[],sessions=parsed.sessions.map(s=>{const old=core().sessions.find(o=>o.id===s.id);if(!old)return {...s};const out={...old,...s};for(const f of ['status','minutes','km','rpe','pain','notes','sleep','shoe','fatigue','weather','packKg','avgHr']){if(filled(old[f])){if(filled(s[f])&&String(s[f])!==String(old[f]))conflicts.push(`${s.date} / ${f}`);out[f]=old[f]}}return out});for(const old of core().sessions)if(!sessions.some(s=>s.id===old.id))sessions.push({...old});const hs=new Map(parsed.health.map(h=>[h.date,{...h}]));for(const old of core().health){const h=hs.get(old.date);if(!h){hs.set(old.date,{...old});continue}for(const [k,v]of Object.entries(old))if(k!=='date'&&filled(v)){if(filled(h[k])&&String(v)!==String(h[k]))conflicts.push(`${old.date} / ${k}`);h[k]=v}}return {sessions:sessions.sort((a,b)=>a.date.localeCompare(b.date)),health:[...hs.values()].sort((a,b)=>a.date.localeCompare(b.date)),conflicts}}
async function readExcel(file){if(file.size>2*1024*1024)throw Error('Classeur supérieur à 2 Mo : modèle trop volumineux pour la sauvegarde locale intégrale.');const buffer=await file.arrayBuffer(),sheets=await parseXlsx({arrayBuffer:async()=>buffer});for(const [name,first]of [['Base séances','ID séance'],['Journal','Sem.'],['Poids & santé','Date']])if(sheets[name]?.[0]?.[0]!==first)throw Error('En-têtes incompatibles dans '+name);const parsed=fromSheets(sheets);if(!parsed.sessions.length)throw Error('Plan vide');const errors=MagnumValidation.validateImport(parsed);if(errors.length)throw Error(errors.slice(0,5).join('; '));if(parsed.unmatched)throw Error(parsed.unmatched+' ligne(s) Journal non rapprochée(s). Aucune importation.');const merged=mergeExcel(parsed),next={...state,core:{...core(),sessions:merged.sessions,health:merged.health},template:excelBase64(buffer)};AlbaStore.validate(next);return {parsed,buffer,conflicts:merged.conflicts}}
async function readRestore(file){if(file.size>8*1024*1024)throw Error('Sauvegarde > 8 Mo');const payload=JSON.parse(await file.text());const restored=AlbaStore.normalize(payload);if(Array.isArray(payload.sessions)&&Array.isArray(payload.health)){const out=structuredClone(state);out.core=restored.core;return AlbaStore.validate(out)}if(restored.template){const sheets=await parseXlsx({arrayBuffer:async()=>excelBuffer(restored.template)});fromSheets(sheets)}return restored}
const actions={
 close:closeSheet,
 more:()=>showSheet('Plus',`<div class="menu-grid">${['trail','events','data','settings'].map(k=>`<button data-nav="${k}">${icon(k)}<span>${labels[k]}</span>${icon('arrow')}</button>`).join('')}</div>`),
 theme:()=>commit(d=>{d.settings.theme=({auto:'dark',dark:'light',light:'auto'})[d.settings.theme]},'Thème : '+({auto:'graphite',dark:'clair',light:'automatique'})[state.settings.theme]),
 customize:()=>{customizing=!customizing;render()},
 'customize-from-settings':()=>{customizing=true;openView('home')},
 'default-layout':()=>{if(confirm('Rétablir l’ordre par défaut du tableau de bord ? Aucune donnée sportive ne sera effacée.'))commit(d=>{d.settings.order=AlbaStore.fresh().settings.order;d.settings.sizes={}})},
 'new-health':()=>healthSheet(), 'new-session':newSession,'new-pack':()=>packSheet(),'new-strength':()=>strengthSheet(),adapt:adaptSheet,
 backup:()=>{AlbaStore.validate(state);download('MAGNUM_OPUS_sauvegarde_complete_'+today()+'.json',JSON.stringify(AlbaStore.backup(state),null,2));toast('Sauvegarde complète générée.')},
 'raw-export':()=>{const all={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k.startsWith('magnum'))all[k]=localStorage.getItem(k)}download('MAGNUM_OPUS_donnees_brutes.json',JSON.stringify(all,null,2));},
 'previous-export':()=>{const raw=localStorage.getItem(AlbaStore.PRE);if(!raw)return toast('Aucun état avant restauration conservé.');download('MAGNUM_OPUS_avant_restauration.json',JSON.stringify(AlbaStore.backup(AlbaStore.normalize(JSON.parse(raw))),null,2))},
 'csv-export':()=>exportCSV(core().sessions.map(s=>({...s,adaptationFactor:state.adaptations[s.id]?.factor,adaptationReason:state.adaptations[s.id]?.reason})),['id','week','date','phase','title','category','status','plannedKm','plannedMinutes','plannedRpe','plannedPackKg','minutes','km','rpe','packKg','avgHr','restHr','sleep','pain','notes','shoe','fatigue','weather','adaptationFactor','adaptationReason'],'MAGNUM_OPUS_journal.csv'),
 'health-csv':()=>exportCSV(core().health,['date','weight','restHr','hrv','sleep','fatigue','pain','stress','notes'],'MAGNUM_OPUS_sante.csv'),
 'excel-export':async()=>{toast('Préparation de la nouvelle copie Excel…');const blob=await ExcelExchange.exportWorkbook(state.template,core());download('MAGNUM_OPUS_ALBA_3_6_export_'+today()+'.xlsx',blob);toast('Copie Excel générée. Conserve aussi le JSON pour les modules complémentaires.')},
 'commit-import':()=>{if(!pendingImport)return;const merged=mergeExcel(pendingImport.parsed);if(!confirm(`Importer ${merged.sessions.length} séances ? ${merged.conflicts.length} conflit(s) conserveront les valeurs locales. Le classeur original n’est pas modifié.`))return;const p=pendingImport;if(commit(d=>{d.core={...d.core,sessions:merged.sessions,health:merged.health,importedAt:new Date().toISOString()};d.template=excelBase64(p.buffer)},'Import 3.6 enregistré.')){pendingImport=null;render()}},
 'commit-restore':()=>{if(!pendingRestore)return;if(!confirm('Remplacer toutes les données locales par cette sauvegarde ? Une copie préalable locale sera conservée.'))return;try{AlbaStore.write(pendingRestore,{restore:true});state=pendingRestore;blocked=null;pendingRestore=null;selectedWeek=null;render();toast('Restauration enregistrée et relue avec succès.')}catch(e){toast('Restauration refusée : '+e.message)}},
 'trail-export':()=>download('MAGNUM_OPUS_preparation_trails.json',JSON.stringify({schemaVersion:2,createdAt:new Date().toISOString(),checks:state.trail,packLog:state.pack,equipment:state.ultimate.equipment,notes:state.extras},null,2)),
 persist:async()=>{const ok=await navigator.storage?.persist?.();toast(ok?'Stockage persistant accordé par le navigateur.':'Le navigateur n’a pas accordé le stockage persistant. Conserve un JSON.')},
 install:async()=>{if(!installPrompt)return toast('Utilise le menu du navigateur → Installer / Ajouter à l’écran d’accueil.');await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null},
 'check-update':async()=>{const reg=await navigator.serviceWorker?.getRegistration();if(!reg)return toast('Service worker indisponible : utilise HTTPS.');await reg.update();toast(reg.waiting?'Une mise à jour est prête.':'Vérification demandée ; la version active reste disponible.')},
 update:()=>{if(!swWaiting)return;if(confirm('Activer la mise à jour maintenant ? Enregistre tout formulaire ouvert avant de continuer.'))swWaiting.postMessage({type:'SKIP_WAITING'})}
};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.nav)return openView(b.dataset.nav);
 if(b.dataset.action){await actions[b.dataset.action]?.();return}
 if(b.dataset.session)return sessionSheet(b.dataset.session);
 if(b.dataset.health)return healthSheet(b.dataset.health);
 if(b.dataset.pack)return packSheet(b.dataset.pack);
 if(b.dataset.strength)return strengthSheet(b.dataset.strength);
 if(b.dataset.planmode){planMode=b.dataset.planmode;render();return}
 if(b.dataset.size){commit(d=>{d.settings.sizes=d.settings.sizes||{};d.settings.sizes[b.dataset.size]=({default:'compact',compact:'wide',wide:'default'})[d.settings.sizes[b.dataset.size]||'default']},'Largeur enregistrée pour tablette et ordinateur.');return}
 if(b.dataset.order){const i=state.settings.order.indexOf(b.dataset.order),j=i+Number(b.dataset.direction);commit(d=>{[d.settings.order[i],d.settings.order[j]]=[d.settings.order[j],d.settings.order[i]]},'Disposition enregistrée.');return}
 if(b.dataset.calday){const ss=core().sessions.filter(s=>s.date===b.dataset.calday);return showSheet(pretty(b.dataset.calday),ss.map(sessionCard).join('')||'<div class="empty">Aucune séance ce jour.</div>')}
 if(b.dataset.event){commit(d=>d.settings.event=b.dataset.event,'Mode événement enregistré.');return}
 if(b.dataset.saveEvent){const n=$('event-notes').value;commit(d=>d.extras['event-'+b.dataset.saveEvent]=n);return}
 if(b.dataset.cancelAdaptation){if(confirm('Annuler cette adaptation et revenir au plan de référence ?')){commit(d=>{delete d.adaptations[b.dataset.cancelAdaptation];d.ultimate.decisions.push({date:today(),action:'Adaptation annulée',sessionId:b.dataset.cancelAdaptation})});closeSheet()}return}
 if(b.dataset.deleteHealth){if(confirm('Effacer les mesures de cette date ? La date du calendrier sera conservée.')){commit(d=>{const h=d.core.health.find(h=>h.date===b.dataset.deleteHealth);for(const k of ['weight','sleep','restHr','hrv','fatigue','pain','stress'])h[k]=null;h.notes=''});closeSheet()}return}
 if(b.dataset.deletePack){if(confirm('Supprimer cette marche ?')){commit(d=>d.pack=d.pack.filter(p=>p.id!==b.dataset.deletePack));closeSheet()}return}
 if(b.dataset.deleteStrength){if(confirm('Supprimer ce renforcement ?')){commit(d=>d.ultimate.strength=d.ultimate.strength.filter(s=>s.id!==b.dataset.deleteStrength));closeSheet()}return}
 if(b.dataset.garmin){const i=Number(b.dataset.garmin),row=garminRows[i],id=$('garmin-match-'+i).value;if(!id)return toast('Choisis une correspondance.');const sessions=MagnumActivityLink.applyOne(core().sessions,row,id);if(commit(d=>d.core.sessions=sessions,'Activité rapprochée et enregistrée.')){row.applied=true;render()}return}
 }catch(err){toast(err.message)}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='week-select'){selectedWeek=el.value;render()}
 if(el.id==='session-filter'){filter=el.value;render()}
 if(el.id==='calendar-month'){calendarMonth=el.value;render()}
 if(el.id==='analysis-window'){analysisWindow=Number(el.value);render()}
 if(el.id==='analysis-category'){analysisCategory=el.value;render()}
 if(el.id==='health-filter'){healthFilter=el.value;render()}
 if(el.id==='theme-select')commit(d=>d.settings.theme=el.value);
 if(el.dataset.check)commit(d=>d.trail[el.dataset.check]=el.checked);
 if(el.dataset.gear)commit(d=>d.ultimate.equipment[el.dataset.gear]=el.checked);
 if(el.id==='scenario-factor'){$('scenario-value').textContent=fmt(planned(core().sessions.filter(s=>s.date>=today()&&s.date<=shift(today(),13)))*Number(el.value))+' km sur 14 jours selon cette hypothèse ; aucune séance modifiée, sans garantie de réalisation.'}
 if(el.id==='excel-input'&&el.files[0]){$('import-preview').innerHTML='<div class="notice">Lecture et contrôle…</div>';pendingImport=null;try{pendingImport=await readExcel(el.files[0]);$('import-preview').innerHTML=importPreview()}catch(err){$('import-preview').innerHTML=`<div class="notice">Import refusé : ${esc(err.message)}</div>`}}
 if(el.id==='restore-input'&&el.files[0]){pendingRestore=null;try{pendingRestore=await readRestore(el.files[0]);$('restore-preview').innerHTML=restorePreview()}catch(err){$('restore-preview').innerHTML=`<div class="notice">Restauration refusée : ${esc(err.message)}</div>`}}
 if(el.id==='garmin-input'&&el.files[0]){garminRows=[];try{const parsed=MagnumActivityCsv.parse(await el.files[0].text()),preview=MagnumActivityLink.preview(parsed,core().sessions);if(preview.rows.length>200)throw Error('Maximum 200 activités par aperçu. Découpe le CSV.');garminRows=preview.rows;$('garmin-preview').innerHTML=garminPreview()}catch(err){$('garmin-preview').innerHTML=`<div class="notice">Import CSV refusé : ${esc(err.message)}</div>`}}
 }catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='session-search'){search=e.target.value;planFiltersOpen=Boolean(document.querySelector('.plan-filters')?.open);const input=e.target,position=input.selectionStart;render();$('session-search')?.focus();$('session-search')?.setSelectionRange(position,position)}});
document.addEventListener('submit',e=>{const form=e.target,formId=form.getAttribute('id');if(!['session-form','health-form','pack-form','strength-form','notes-form','new-session-form','adapt-form'].includes(formId))return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),numbers=ks=>Object.fromEntries(ks.map(k=>[k,num(data[k])])),uuid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);let ok=false;
 if(formId==='session-form')ok=commit(d=>{Object.assign(d.core.sessions.find(s=>s.id===form.dataset.id),numbers(['minutes','km','rpe','pain','packKg','avgHr','sleep','fatigue']),{status:data.status,notes:data.notes,shoe:data.shoe,weather:data.weather})});
 if(formId==='health-form'){if(!MagnumValidation.validISODate(data.date))return toast('Date invalide');const h={date:data.date,...numbers(['weight','sleep','restHr','hrv','fatigue','pain','stress']),notes:data.notes};ok=commit(d=>{const old=d.core.health.find(h=>h.date===data.date);const fields={...old,...h};d.core.health=[...d.core.health.filter(x=>x.date!==data.date),fields].sort((a,b)=>a.date.localeCompare(b.date))})}
 if(formId==='pack-form')ok=commit(d=>{const p={id:form.dataset.id||uuid(),date:data.date,...numbers(['km','weight','ascent','rpe'])};d.pack=[...d.pack.filter(x=>x.id!==p.id),p]});
 if(formId==='strength-form')ok=commit(d=>{const s={id:form.dataset.id||uuid(),date:data.date,type:data.type,notes:data.notes,...numbers(['minutes','rpe'])};d.ultimate.strength=[...d.ultimate.strength.filter(x=>x.id!==s.id),s]});
 if(formId==='notes-form')ok=commit(d=>d.extras.notes=data.notes);
 if(formId==='new-session-form')ok=commit(d=>{d.core.sessions.push({id:'manual-'+uuid(),week:d.core.sessions.find(s=>s.date===data.date)?.week||'libre',date:data.date,title:data.title,category:data.category,phase:'Journal libre',rest:false,status:'Réalisé',plannedKm:null,plannedMinutes:null,plannedRpe:null,notes:'',...numbers(['minutes','km','rpe'])});d.core.sessions.sort((a,b)=>a.date.localeCompare(b.date))});
 if(formId==='adapt-form'){if(!confirm('Valider cette adaptation ? Le plan de référence sera conservé et une proposition distincte sera affichée sur la séance.'))return;ok=commit(d=>{d.adaptations[data.id]={factor:Number(data.factor),reason:data.reason,date:today()};d.ultimate.decisions.push({id:uuid(),date:today(),action:'Adaptation validée',sessionId:data.id,factor:Number(data.factor),suggestion:data.reason})})}
 if(ok&&formId!=='notes-form')closeSheet();
});
window.addEventListener('hashchange',()=>{const k=location.hash.slice(1);if(labels[k]&&k!==view){view=k;render()}});
window.addEventListener('online',shell);window.addEventListener('offline',shell);
window.addEventListener('storage',e=>{if(e.key===AlbaStore.KEY){try{state=AlbaStore.load().data;render();toast('Données mises à jour depuis un autre onglet.')}catch(err){blocked=err.message;render()}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
async function checkOffline(){const el=$('offline-ready');if(!el)return;try{const reg=await navigator.serviceWorker?.getRegistration();const keys=await caches.keys();el.textContent=reg?.active&&keys.includes('alba-4.0.0')?'Cache prêt':'Première ouverture en cours'}catch{el.textContent='Indisponible'}}
async function initSW(){if(!('serviceWorker'in navigator)||location.protocol==='file:')return;try{const reg=await navigator.serviceWorker.register('./sw.js');function ready(){if(reg.waiting){swWaiting=reg.waiting;shell()}}ready();reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'){ready();checkOffline()}})});let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(swWaiting&&!refreshing){refreshing=true;location.reload()}})}catch(e){toast('Hors ligne non initialisé : '+e.message)}}
async function init(){render();if(!blocked&&core().sessions.length===0){try{const ref=await fetch('./plan-reference.json').then(r=>{if(!r.ok)throw Error('Plan de référence introuvable');return r.json()});commit(d=>{d.core.sessions=ref.sessions;d.core.referenceSource=ref.source},'')}catch(e){toast('Plan non chargé : '+e.message)}}initSW()}
init();
